-- Toy Shop · Milestone 5: 30 demo toys so the shop looks full while you set up.
-- Run once in Supabase → SQL Editor, after 0002_catalog.sql. Safe to run again.
-- Remove them any time from the owner dashboard ("Remove all demo toys").
-- Demo photos live in the website itself (apps/web/public/demo), not in Supabase storage.

alter table public.products add column if not exists is_demo boolean not null default false;

insert into public.products (
  slug, name, category_id, age_group, price_paise, mrp_paise, stock, gst_rate,
  weight_grams, is_featured, short_description, description, sku, brand,
  status, is_demo, created_at
)
select
  v.slug, v.name, c.id, v.age_group, v.price_paise, v.mrp_paise, v.stock, v.gst_rate,
  v.weight_grams, v.is_featured, v.short_description, v.description, v.sku, 'Toby Toys',
  'published', true, now() - make_interval(hours => v.ord * 7)
from (values
  ('remote-control-monster-truck', 'Remote Control Monster Truck', 'vehicles', '6-8', 129900, 189900, 14, 18, 950, true, 'Big bouncy wheels that climb over anything!', 'This rugged monster truck zooms forward, backward and spins on the spot. Rubber tyres with real suspension handle carpets, tiles and garden paths. Rechargeable battery gives about 25 minutes of play. Includes USB charging cable and an easy two-stick remote.', 'DEMO-001', 0),
  ('wooden-pull-along-train', 'Wooden Pull-Along Train Set', 'vehicles', '3-5', 89900, 119900, 20, 12, 700, false, 'Four colourful carriages that link with magnets', 'A classic wooden train with an engine and four carriages that connect with gentle magnets. Smooth rounded edges and child-safe water-based paints. Pull it along with the string or stack the coloured blocks inside each carriage. Great for counting, colours and imaginative play.', 'DEMO-002', 1),
  ('die-cast-fire-engine', 'Die-Cast Fire Engine', 'vehicles', '3-5', 44900, 59900, 3, 12, 300, false, 'Extending ladder, lights and siren sounds', 'A sturdy metal-and-plastic fire engine with a ladder that lifts and extends. Press the button for flashing lights and a siren. Pull-back motor makes it race across the floor. Batteries included.', 'DEMO-003', 2),
  ('friction-police-car', 'Friction Powered Police Car', 'vehicles', '3-5', 29900, null, 40, 12, 200, false, 'Push, let go and watch it zoom — no batteries!', 'Give it a push and the friction motor sends this police car speeding away. No batteries needed, ever. Tough body survives bumps and drops. The perfect pocket-money toy and party return gift.', 'DEMO-004', 3),
  ('jungle-animals-jigsaw-100', '100-Piece Jungle Animals Jigsaw Puzzle', 'puzzles', '6-8', 34900, null, 25, 12, 400, false, 'Lions, elephants and parrots in one bright puzzle', 'A colourful 100-piece jigsaw full of jungle animals. Thick, sturdy pieces that are easy for small hands. Finished size 48 × 34 cm. Comes with a picture poster to help, and a zip bag for storage.', 'DEMO-005', 4),
  ('india-map-floor-puzzle', 'India Map Floor Puzzle', 'puzzles', '6-8', 59900, 74900, 18, 12, 650, true, 'Learn every state and capital while you play', 'A giant 60 × 60 cm floor puzzle of India with every state, its capital, famous monuments and animals. Big foam-backed pieces are easy to wipe clean. A fun way to learn geography with the whole family.', 'DEMO-006', 5),
  ('wooden-shape-sorter-cube', 'Wooden Shape Sorter Cube', 'puzzles', '0-2', 49900, 69900, 15, 12, 800, false, 'Twelve chunky shapes, six colourful sides', 'Babies and toddlers post twelve chunky wooden shapes through the matching holes. Builds hand–eye coordination, shape recognition and patience. The lid opens easily to get the shapes back out. Non-toxic paint, smooth sanded edges.', 'DEMO-007', 6),
  ('magic-speed-cube', 'Magic Speed Cube 3×3', 'puzzles', '9-12', 24900, 39900, 50, 12, 100, false, 'Smooth, fast turning — beat your best time!', 'A smooth-turning 3×3 puzzle cube with bright stickerless colours. Adjustable tension for beginners and speed-solvers alike. Comes with a step-by-step solving guide for first-timers.', 'DEMO-008', 7),
  ('cuddly-teddy-bear-30cm', 'Cuddly Teddy Bear (30 cm)', 'soft-toys', '0-2', 59900, 89900, 30, 12, 350, true, 'Super-soft, huggable and safe from day one', 'Our best-loved teddy, made with extra-soft plush and safety-stitched eyes. Filled with hypoallergenic fibre. Machine washable on a gentle cycle. The perfect first friend and a wonderful gift for newborns.', 'DEMO-009', 8),
  ('plush-elephant-pillow', 'Plush Elephant Pillow', 'soft-toys', '0-2', 69900, 99900, 12, 12, 450, false, 'A cuddly friend and a comfy pillow in one', 'This gentle grey elephant doubles as a soft pillow for naps and story time. Long trunk and floppy ears to squeeze. Removable, washable cover. 45 cm long.', 'DEMO-010', 9),
  ('sleepy-bunny-soft-toy', 'Sleepy Bunny Soft Toy', 'soft-toys', '3-5', 44900, null, 22, 12, 250, false, 'Long floppy ears made for bedtime cuddles', 'A sleepy bunny with embroidered closed eyes and extra-long ears. Lightweight and easy to carry everywhere. Soft enough for bedtime, tough enough for adventures.', 'DEMO-011', 10),
  ('unicorn-plush-rainbow-mane', 'Unicorn Plush with Rainbow Mane', 'soft-toys', '3-5', 79900, 109900, 2, 12, 400, false, 'A sparkly golden horn and a rainbow mane', 'A magical unicorn with a shimmering golden horn, rainbow mane and tail you can brush. Glitter hooves and big friendly eyes. 35 cm tall.', 'DEMO-012', 11),
  ('washable-crayons-48', 'Washable Crayons Mega Box (48)', 'art-craft', '3-5', 24900, 29900, 60, 12, 450, false, '48 bright colours that wash off walls and clothes', 'Forty-eight bold, smooth crayons that wash off skin, clothes and most walls with soap and water. Thick, break-resistant crayons for little hands. Non-toxic and safe.', 'DEMO-013', 12),
  ('clay-modelling-kit', 'Clay Modelling Kit', 'art-craft', '6-8', 39900, 54900, 35, 12, 600, false, '12 soft clay colours with tools and moulds', 'Twelve tubs of soft, non-sticky modelling clay plus shaping tools, cutters and animal moulds. Clay stays soft for weeks when the lids are closed. Hours of screen-free creativity.', 'DEMO-014', 13),
  ('rangoli-colour-art-set', 'Rangoli Colour Art Set', 'art-craft', '6-8', 34900, null, 20, 12, 500, false, 'Make festive rangoli with stencils and colours', 'Everything for beautiful rangoli: eight bright colour powders, six reusable stencils and a fine-tip shaker. Perfect for Diwali, Pongal and every celebration. Easy to sweep up after.', 'DEMO-015', 14),
  ('friendship-bracelet-kit', 'DIY Friendship Bracelet Kit', 'art-craft', '9-12', 29900, 39900, 0, 12, 250, false, 'Make 20 colourful bracelets for your friends', 'A complete kit with coloured threads, beads, letter charms and an easy braiding wheel. Step-by-step picture guide included. Make up to 20 bracelets to share.', 'DEMO-016', 15),
  ('junior-science-lab-kit', 'Junior Science Lab Kit', 'learning', '9-12', 89900, 99900, 10, 12, 1100, true, '30 safe experiments that fizz, glow and grow', 'Thirty fun, safe experiments with a real mini microscope, test tubes, measuring cups and goggles. Make volcanoes erupt, grow crystals and see tiny worlds up close. Clear illustrated guide in English.', 'DEMO-017', 16),
  ('wooden-abacus', 'Wooden Abacus Counting Frame', 'learning', '3-5', 34900, 44900, 28, 12, 550, false, '100 colourful beads for counting and maths', 'A classic abacus with 100 bright wooden beads on ten rods. Makes counting, adding and subtracting easy to see and touch. Solid wooden frame with a stable base.', 'DEMO-018', 17),
  ('tamil-english-alphabet-blocks', 'Tamil & English Alphabet Blocks', 'learning', '3-5', 54900, 69900, 16, 12, 900, false, 'Learn letters in two languages, block by block', 'Thirty smooth wooden blocks printed with Tamil letters, English letters, numbers and pictures. Stack, sort and spell. A playful way to grow up bilingual.', 'DEMO-019', 18),
  ('solar-system-glow-model', 'Solar System Glow Model', 'learning', '9-12', 74900, 99900, 8, 12, 700, false, 'Paint the planets — they glow in the dark!', 'Build and paint your own hanging solar system. Includes eight planets, the Sun, glow-in-the-dark paint, brush and a star chart. Hang it from the ceiling for a glowing space adventure at bedtime.', 'DEMO-020', 19),
  ('kids-cricket-set-size-3', 'Kids Cricket Set (Size 3)', 'outdoor', '6-8', 99900, 149900, 12, 12, 1400, true, 'Bat, ball, stumps and bails — ready to play!', 'A complete junior cricket set: a lightweight size-3 bat, soft cricket ball, three stumps, bails and a carry bag. Perfect for the park, terrace or beach.', 'DEMO-021', 20),
  ('bubble-blaster-wand', 'Bubble Blaster Wand', 'outdoor', '3-5', 19900, 24900, 45, 12, 200, false, 'Hundreds of bubbles with one big swoosh', 'Dip and swoosh to make clouds of bubbles. Comes with a no-spill tray and a bottle of non-toxic bubble solution. Endless garden fun.', 'DEMO-022', 21),
  ('rainbow-kite-with-string', 'Rainbow Kite with String', 'outdoor', '6-8', 14900, null, 70, 12, 150, false, 'Easy to fly, even on a gentle breeze', 'A bright rainbow kite with a long tail that flies easily in light wind. Includes 30 metres of string on a handy winder. Perfect for Sankranti and breezy evenings.', 'DEMO-023', 22),
  ('soft-football-size-3', 'Soft Football (Size 3)', 'outdoor', '6-8', 39900, 49900, 25, 12, 350, false, 'Soft-touch football that''s kind to little feet', 'A size-3 football with a soft, cushioned cover — safe for younger players and windows. Holds air well. Pump not included.', 'DEMO-024', 23),
  ('musical-keyboard-32-keys', 'Musical Keyboard (32 Keys)', 'electronic', '3-5', 119900, 159900, 9, 18, 900, false, 'Eight instruments, demo songs and a microphone', 'A 32-key keyboard with eight instrument sounds, drum beats, eight demo songs and a microphone for singing along. Volume control keeps the peace at home. Runs on batteries or USB.', 'DEMO-025', 24),
  ('walkie-talkie-pair', 'Walkie-Talkie Pair for Kids', 'electronic', '6-8', 109900, 139900, 6, 18, 400, false, 'Talk to friends up to 1 km away', 'Two easy-to-use walkie-talkies with a range of up to 1 km in open spaces. Clear sound, belt clips and a built-in torch. Great for camping, games and adventures.', 'DEMO-026', 25),
  ('coding-robot-buddy', 'Coding Robot Buddy', 'electronic', '9-12', 249900, 299900, 4, 18, 1200, true, 'Learn to code by giving your robot commands', 'A friendly robot that kids program with picture cards or a free app. Teaches sequencing, loops and problem-solving through games. It dances, draws lines and avoids obstacles. Rechargeable.', 'DEMO-027', 26),
  ('rainbow-stacking-rings', 'Rainbow Wooden Stacking Rings', 'baby', '0-2', 49900, 79900, 18, 12, 500, false, 'Soft colours, smooth wood, loved by toddlers', 'Seven rainbow rings to stack in order on a wooden pole. Teaches sizes, colours and fine motor skills. Smooth, chunky pieces made for little hands. Child-safe paint.', 'DEMO-028', 27),
  ('baby-rattle-set', 'Baby Rattle Set (4 pcs)', 'baby', '0-2', 34900, 44900, 24, 12, 200, false, 'Four gentle rattles that are easy to grip', 'Four lightweight rattles in different shapes and sounds. Easy-grip handles and soft textures for teething gums. BPA-free and easy to wash.', 'DEMO-029', 28),
  ('baby-activity-play-gym', 'Baby Activity Play Gym', 'baby', '0-2', 199900, 269900, 7, 12, 1800, false, 'A soft play mat with hanging toys and a mirror', 'A padded play mat with two soft arches, five hanging toys, a baby-safe mirror and crinkle textures. Supports tummy time and reaching. Folds flat for storage and travel.', 'DEMO-030', 29)
) as v (slug, name, category_slug, age_group, price_paise, mrp_paise, stock, gst_rate,
        weight_grams, is_featured, short_description, description, sku, ord)
left join public.categories c on c.slug = v.category_slug
on conflict (slug) do nothing;

insert into public.product_images (product_id, storage_path, alt_text, position)
select p.id, 'demo/' || p.slug || '.webp', p.name, 0
from public.products p
where p.is_demo
  and not exists (select 1 from public.product_images i where i.product_id = p.id);
